            }
            "exit" => {
                self.quit_requested.store(true, Ordering::Release);
                Ok(json!({ "requested": "application_exit" }))
            }
            _ => Err(BridgeError::new(
                "internal",
                "method routed but not handled",
            )),
        }
    }
}

