                Ok(json!({ "path": folder }))
            }
            "openUrl" => {
                let url = payload.get("url").and_then(|v| v.as_str()).ok_or_else(|| {
                    BridgeError::with_details(
                        "invalid_payload",
                        "expected JSON object with string field \"url\"",
                        payload.clone(),
                    )
                })?;
                if !(url.starts_with("https://") || url.starts_with("http://")) {
                    return Err(BridgeError::new(
                        "invalid_url",
