    }

    #[test]
    fn accepts_nested() {
        let root = Path::new("/tmp/sandbox");
        let p = resolve_under_sandbox(root, "a/b/c.txt").unwrap();
        assert_eq!(p, PathBuf::from("/tmp/sandbox/a/b/c.txt"));
