    let file = parse_component_file(content)?;
    let component = file
        .components
        .get(component_name)
        .ok_or_else(|| CrepusError::render(format!("component not found: {component_name}")))?;

    let mut child_ctx = ctx.clone();
    for (key, expr) in &component.meta.defaults {
